import { readFile } from 'node:fs/promises';
import { resolve, dirname, relative } from 'node:path';
const ROOT = '/home/user/Claudinite';
const entry = resolve(ROOT, 'packs/claudinite-dashboard/app.mjs');
const seen = new Set();
const bad = [];
async function walk(file) {
  if (seen.has(file)) return;
  seen.add(file);
  const src = await readFile(file, 'utf8');
  const code = src.replace(/^\s*\/\/.*$/gm, '');
  for (const m of code.matchAll(/from\s+'([^']+)'/g)) {
    const spec = m[1];
    if (spec.startsWith('node:')) { bad.push([relative(ROOT, file), spec]); continue; }
    if (!spec.startsWith('.')) { bad.push([relative(ROOT, file), 'bare: ' + spec]); continue; }
    await walk(resolve(dirname(file), spec));
  }
  if (/\bprocess\./.test(code)) bad.push([relative(ROOT, file), 'process.']);
  if (/\brequire\s*\(/.test(code)) bad.push([relative(ROOT, file), 'require()']);
}
await walk(entry);
console.log('reachable files:', seen.size);
console.log([...seen].map(f => relative(ROOT, f)).sort().join('\n'));
console.log('\nVIOLATIONS:');
console.log(bad.map(b => b.join('  ->  ')).join('\n') || '(none)');
EOF
