import { chromium } from 'playwright';
const [,, url, shot] = process.argv;
const b = await chromium.launch();
const p = await b.newPage();
const errs = [];
p.on('console', m => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
p.on('pageerror', e => errs.push('pageerror: ' + e.message));
p.on('requestfailed', r => errs.push('requestfailed: ' + r.url() + ' ' + (r.failure()?.errorText ?? '')));
await p.goto(url, { waitUntil: 'networkidle' });
if (shot) await p.screenshot({ path: shot, fullPage: false });
console.log('title:', await p.title());
console.log('body chars:', (await p.innerText('body')).length);
console.log(errs.length ? errs.join('\n') : 'no errors');
await b.close();
